# brain/driver.py -- Raspberry Pi 5 motor + steering control for the RC crawler.
#
# Throttle (ESC) and steering (servo) PWM are generated by a PCA9685 over I2C, so the
# pulse timing stays rock-solid even while the Pi is busy running the LLM. A forward
# HC-SR04 (read on Pi GPIO via gpiozero) refuses forward motion under OBSTACLE_CM.
#
# SAFETY: the old design had a Pico hardware watchdog; that is gone now, so a software
# failsafe takes its place. A background control thread forces the ESC back to NEUTRAL
# when a move's deadline passes, on STOP, on any error, or when an obstacle is detected
# ahead. The ESC is armed at neutral on startup.
#   LIMITATION: if the whole Python process is killed, the PCA9685 holds the last pulse
#   it was given. There is no hardware watchdog to catch that -- keep a PHYSICAL kill
#   switch on the motor battery within reach (see README).
#
# Threading model: ALL PCA9685 (I2C) writes go through self._io. State is guarded by
# self._lock. The control thread is the ONLY place that drives the PWM outputs during
# normal operation; command()/stop() only mutate state, so two threads never issue
# overlapping I2C transactions.

import os
import threading
import time

from adafruit_servokit import ServoKit
from gpiozero import DistanceSensor

VALID_DRIVE = {"FORWARD", "REVERSE", "STOP"}
VALID_STEER = {"LEFT", "CENTER", "RIGHT"}


def _envf(key, default):
    try:
        return float(os.environ.get(key, default))
    except (TypeError, ValueError):
        return float(default)


def _envi(key, default):
    try:
        return int(os.environ.get(key, default))
    except (TypeError, ValueError):
        return int(default)


class RobotDriver:
    """Owns all PWM output and the safety control loop. Thread-safe."""

    def __init__(self):
        # --- PCA9685 channels ---
        self.esc_ch = _envi("ROBOT_ESC_CHANNEL", 0)
        self.steer_ch = _envi("ROBOT_STEER_CHANNEL", 1)
        channels = _envi("ROBOT_PCA9685_CHANNELS", 16)

        # --- Steering geometry (servo degrees). Calibrate so wheels point straight at CENTER. ---
        self.steer_center = _envf("ROBOT_STEER_CENTER", 90.0)
        self.steer_left = _envf("ROBOT_STEER_LEFT", 55.0)
        self.steer_right = _envf("ROBOT_STEER_RIGHT", 125.0)

        # --- Throttle: a loaded crawler should stay slow. max_throttle caps the ESC range. ---
        self.max_throttle = _envf("ROBOT_MAX_THROTTLE", 0.35)   # 0..1 fraction of full ESC range
        self.invert = _envi("ROBOT_THROTTLE_INVERT", 0) == 1     # flip if FWD/REV are swapped
        self.arm_secs = _envf("ROBOT_ESC_ARM_SECS", 3.0)

        # --- Forward obstacle gate ---
        self.obstacle_cm = _envf("ROBOT_OBSTACLE_CM", 30.0)
        trig = _envi("ROBOT_TRIG_PIN", 23)
        echo = _envi("ROBOT_ECHO_PIN", 24)

        # --- Failsafe: absolute cap on how long one command may keep the motor running ---
        self.max_move_ms = _envi("ROBOT_MAX_MOVE_MS", 5000)

        # --- Locks: _io serializes every I2C write; _lock guards shared state. ---
        self._io = threading.Lock()
        self._lock = threading.Lock()

        self.kit = ServoKit(channels=channels)
        # ESC behaves like a continuous-rotation servo: throttle -1..1, 0 == neutral.
        self.kit.continuous_servo[self.esc_ch].set_pulse_width_range(1000, 2000)
        self.kit.servo[self.steer_ch].set_pulse_width_range(500, 2500)
        self.kit.servo[self.steer_ch].actuation_range = 180

        # A short echo queue keeps the obstacle stop responsive (less smoothing lag).
        self.sensor = DistanceSensor(echo=echo, trigger=trig, max_distance=4.0, queue_len=3)

        # --- Shared state (guarded by _lock) ---
        self._drive = "STOP"
        self._steer = "CENTER"
        self._throttle = 0.0          # target magnitude, 0..max_throttle
        self._deadline = 0.0          # time.monotonic() after which we coast to neutral
        self._closed = False
        self.on_obstacle = None       # optional callback(distance_cm) -- keep it non-blocking
        self._last_obstacle = 0.0

        self._arm()                   # ESC must see neutral before it will run (it will beep)
        with self._io:
            self._write_steer("CENTER")

        self._thread = threading.Thread(target=self._control_loop, daemon=True)
        self._thread.start()

    # ---------- public API (mutate state only; the control thread drives the hardware) ----------
    def command(self, drive, steer, speed, duration_ms):
        """Replace the in-flight motion. A new command preempts the previous one."""
        drive = drive if drive in VALID_DRIVE else "STOP"
        steer = steer if steer in VALID_STEER else "CENTER"
        speed = max(0, min(100, int(speed)))
        duration_ms = max(0, min(self.max_move_ms, int(duration_ms)))
        throttle = (speed / 100.0) * self.max_throttle
        with self._lock:
            self._drive = drive
            self._steer = steer
            self._throttle = throttle if drive != "STOP" else 0.0
            self._deadline = time.monotonic() + duration_ms / 1000.0

    def stop(self):
        with self._lock:
            self._drive = "STOP"
            self._throttle = 0.0
            self._deadline = 0.0
        self._neutral()   # don't wait up to one loop tick to cut throttle

    def distance_cm(self):
        try:
            return self.sensor.distance * 100.0
        except Exception:
            return -1.0

    def close(self):
        with self._lock:
            self._closed = True
        if self._thread.is_alive():
            self._thread.join(timeout=1.0)
        self._neutral()
        with self._io:
            self._write_steer("CENTER")
        try:
            self.sensor.close()
        except Exception:
            pass

    # ---------- internals ----------
    def _arm(self):
        self._neutral()
        time.sleep(self.arm_secs)

    def _neutral(self):
        with self._io:
            try:
                self._write_throttle(0.0)
            except Exception:
                pass

    def _write_throttle(self, value):    # caller MUST hold self._io
        if self.invert:
            value = -value
        value = max(-1.0, min(1.0, value))
        self.kit.continuous_servo[self.esc_ch].throttle = value

    def _write_steer(self, steer):       # caller MUST hold self._io
        angle = {"LEFT": self.steer_left, "RIGHT": self.steer_right}.get(steer, self.steer_center)
        self.kit.servo[self.steer_ch].angle = max(0.0, min(180.0, angle))

    def _control_loop(self):
        # Runs at ~20 Hz. This loop is the failsafe AND the sole normal-operation writer of
        # the PWM outputs: it always converges to neutral unless a fresh, unexpired
        # FORWARD/REVERSE command says otherwise.
        while True:
            with self._lock:
                if self._closed:
                    break
                drive, throttle, steer, deadline = (
                    self._drive, self._throttle, self._steer, self._deadline)

            out = 0.0
            if drive in ("FORWARD", "REVERSE") and time.monotonic() <= deadline:
                if drive == "FORWARD":
                    d = self.distance_cm()
                    if 0 <= d < self.obstacle_cm:
                        out = 0.0
                        self._trip_obstacle(d)   # sets state STOP + fires callback
                    else:
                        out = throttle
                else:
                    out = -throttle

            try:
                with self._io:
                    self._write_throttle(out)
                    self._write_steer(steer)
            except Exception:
                self._neutral()
            time.sleep(0.05)

        self._neutral()

    def _trip_obstacle(self, distance_cm):
        with self._lock:
            self._drive = "STOP"
            self._throttle = 0.0
        now = time.monotonic()
        cb = self.on_obstacle
        if cb and now - self._last_obstacle > 3.0:   # debounce
            self._last_obstacle = now
            try:
                cb(distance_cm)
            except Exception:
                pass
